<script module lang="ts">
/**
 * Markdown.Inlines: a block’s inline nodes, each as the member or element that draws its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { inlineText, joinSlot, type MarkdownInline } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import Citation from './Citation.svelte'
import Code from '../structure/Code.svelte'
import Link from '../controls/Link.svelte'
import MarkdownInlines from './MarkdownInlines.svelte'
import type { CitationSource } from './SourceList.svelte'

export interface MarkdownInlinesProps {
  nodes: MarkdownInline[]
  sources: CitationSource[]
}
</script>

<script lang="ts">
let { nodes, sources }: MarkdownInlinesProps = $props()
const joined = joinSlot(undefined, () => ({}))
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#each nodes as node, index (index)
    }{#if node.kind === 'text'
      }{node.text
    }{:else if node.kind === 'code'
      }<Code>{node.text}</Code
    >{:else if node.kind === 'strong'
      }<strong><MarkdownInlines nodes={node.children} {sources} /></strong
    >{:else if node.kind === 'em'
      }<em><MarkdownInlines nodes={node.children} {sources} /></em
    >{:else if node.kind === 'strike'
      }<s><MarkdownInlines nodes={node.children} {sources} /></s
    >{:else if node.kind === 'break'
      }<br
    />{:else if node.kind === 'link'
      }<Link href={node.href} external={/^(https?:|mailto:|\/\/)/i.test(node.href)}
        >{inlineText(node.children)
      }</Link
    >{:else if node.kind === 'image'
      }<img class={styles.image} src={node.src} alt={node.alt} loading="lazy" draggable="false"
    />{:else if node.kind === 'citation' && sources[node.index - 1] !== undefined
      }<Citation index={node.index} source={sources[node.index - 1]!}
    />{:else if node.kind === 'citation'
      }{`[${node.index}]`
    }{/if
  }{/each
}{/if
}{@render joined.end?.()}
